using System;
using System.Diagnostics;
using System.Reflection;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Tests;

[AttributeUsage(AttributeTargets.Method, AllowMultiple = false)]
public sealed class TimedTestMethodAttribute : TestMethodAttribute
{
    public int WarningThresholdMs { get; }

    public TimedTestMethodAttribute(int warningThresholdMs = 5000)
    {
        WarningThresholdMs = warningThresholdMs;
    }
}

[TestClass]
public class PerformanceTests
{
    private Stopwatch? _stopwatch;

    public TestContext TestContext { get; set; } = null!;

    [TestInitialize]
    public void StartTiming()
    {
        _stopwatch = Stopwatch.StartNew();
    }

    [TestCleanup]
    public void StopTiming()
    {
        _stopwatch?.Stop();

        var method = GetType().GetMethod(TestContext.TestName!);
        var attr = method?.GetCustomAttribute<TimedTestMethodAttribute>();
        if (attr is not null && _stopwatch!.ElapsedMilliseconds > attr.WarningThresholdMs)
        {
            Console.WriteLine($"WARNING: {TestContext.TestName} took {_stopwatch.ElapsedMilliseconds}ms (threshold: {attr.WarningThresholdMs}ms)");
        }
    }

    [TimedTestMethod(warningThresholdMs: 1000)]
    [Timeout(0)]
    public void ProcessLargeDataSet_CompletesInTime()
    {
        Assert.IsTrue(true);
    }

    [TimedTestMethod]
    public void QuickCalculation_IsFast()
    {
        Assert.IsTrue(true);
    }

    [TestMethod]
    [Timeout(0)]
    public void LongRunningIntegration_NeverTimesOut()
    {
        Assert.IsTrue(true);
    }
}

